 import { MeshBasicNodeMaterial } from 'three/webgpu';
import { color, texture, uv } from 'three/tsl';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const { Group, Mesh, PlaneGeometry } = THREE;

  const group = new Group();
  group.userData.handlers = {};

  const visual = config.intent?.visualSpec ?? config.visual ?? {};
  const colors = visual.colors ?? config.colors ?? {};
  const items = config.textContent ?? visual.textContent ?? [];

  const paper = colors.paper ?? '#e8ecf2';
  const accent = colors.accent ?? '#ff2a38';
  const surface = colors.surface ?? '#0b0b10';

  const geoms = [];
  const mats = [];
  let texRef = null;

  const cardW = 1.2;
  const cardH = 0.75;
  const cardGeom = new PlaneGeometry(cardW, cardH);
  geoms.push(cardGeom);

  const cardMat = new MeshBasicNodeMaterial();
  cardMat.transparent = true;
  cardMat.colorNode = color(surface);
  mats.push(cardMat);

  const card = new Mesh(cardGeom, cardMat);
  group.add(card);

  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      texRef = tex;
      tex.colorSpace = THREE.SRGBColorSpace;
      tex.minFilter = THREE.LinearFilter;
      tex.magFilter = THREE.LinearFilter;
      cardMat.colorNode = texture(tex, uv());
      cardMat.needsUpdate = true;
    }).catch(() => {});
  }

  const headline = items.find((i) => i.role === 'headline') || items[0];
  if (headline?.text) {
    const textObj = ctx.fontAtlas.createText(headline.text, {
      fontSize: headline.typography?.fontSize ?? 39,
      color: paper,
      align: 'center'
    });
    textObj.position.set(0, 0.06, 0.05);
    group.add(textObj);

    const accentGeom = new PlaneGeometry(0.26, 0.012);
    geoms.push(accentGeom);

    const accentMat = new MeshBasicNodeMaterial();
    accentMat.transparent = true;
    accentMat.colorNode = color(accent);
    mats.push(accentMat);

    const accentLine = new Mesh(accentGeom, accentMat);
    accentLine.position.set(0, -0.08, 0.06);
    group.add(accentLine);
  }

  group.userData.cleanup = () => {
    mats.forEach((m) => m.dispose());
    geoms.forEach((g) => g.dispose());
    if (texRef?.dispose) texRef.dispose();
  };

  return group;
}
